16	package org.springframework.samples.petclinic.model;
17	
18	import org.springframework.core.style.ToStringCreator;
19	
20	import jakarta.persistence.*;
21	import jakarta.validation.constraints.Digits;
22	import jakarta.validation.constraints.NotEmpty;
23	import jakarta.validation.constraints.Pattern;
24	
25	import java.time.LocalDate;
26	import java.util.*;
27	
28	/**
29	 * Simple JavaBean domain object representing an owner.
30	 *
31	 * @author Ken Krebs
32	 * @author Juergen Hoeller
33	 * @author Sam Brannen
34	 * @author Michael Isvy
35	 */
36	@Entity
37	@Table(name = "owners")
38	public class Owner extends Person {
39	    @Column(name = "address")
40	    @NotEmpty
41	    private String address;
42	
43	    @Column(name = "city")
44	    @NotEmpty
45	    private String city;
46	
47	    @Column(name = "telephone")
48	    @NotEmpty
49	    @Digits(fraction = 0, integer = 10)
50	    @Pattern(regexp = "^[0-9]{10}$", message = "Phone number must be exactly 10 digits")
51	    private String telephone;
52	
53	    @Column(name = "email")
54	    private String email;
55	
56	    @Column(name = "registration_date", columnDefinition = "DATE")
57	    private LocalDate registrationDate;
58	
59	    @Column(name = "membership_number")
60	    private Integer membershipNumber;
61	
62	    @Column(name = "customer_code")
63	    private String customerCode;
64	
65	    @Column(name = "membership_tier")
66	    private String membershipTier;
67	
68	    @Column(name = "namesake_count")
69	    private Integer namesakeCount;
70	
71	    @Column(name = "shares_household")
72	    private Boolean sharesHousehold;
73	
74	    @Transient
75	    private String locality;
76	
77	    @OneToMany(cascade = CascadeType.ALL, mappedBy = "owner", fetch = FetchType.EAGER)
78	    private Set<Pet> pets;
79	
80	    public String getAddress() {
81	        return this.address;
82	    }
83	
84	    public void setAddress(String address) {
85	        this.address = address;
86	    }
87	
88	    public String getCity() {
89	        return this.city;
90	    }
91	
92	    public void setCity(String city) {
93	        this.city = city;
94	    }
95	
96	    public String getTelephone() {
97	        return this.telephone;
98	    }
99	
100	    public void setTelephone(String telephone) {
101	        this.telephone = telephone;
102	    }
103	
104	    public String getEmail() {
105	        return this.email;
106	    }
107	
108	    public void setEmail(String email) {
109	        this.email = email;
110	    }
111	
112	    public LocalDate getRegistrationDate() {
113	        return this.registrationDate;
114	    }
115	
116	    public void setRegistrationDate(LocalDate registrationDate) {
117	        this.registrationDate = registrationDate;
118	    }
119	
120	    public Integer getMembershipNumber() {
121	        return this.membershipNumber;
122	    }
123	
124	    public void setMembershipNumber(Integer membershipNumber) {
125	        this.membershipNumber = membershipNumber;
126	    }
127	
128	    public String getCustomerCode() {
129	        return this.customerCode;
130	    }
131	
132	    public void setCustomerCode(String customerCode) {
133	        this.customerCode = customerCode;
134	    }
135	
136	    public String getMembershipTier() {
137	        return this.membershipTier;
138	    }
139	
140	    public void setMembershipTier(String membershipTier) {
141	        this.membershipTier = membershipTier;
142	    }
143	
144	    public Integer getNamesakeCount() {
145	        return this.namesakeCount;
146	    }
147	
148	    public void setNamesakeCount(Integer namesakeCount) {
149	        this.namesakeCount = namesakeCount;
150	    }
151	
152	    public Boolean getSharesHousehold() {
153	        return this.sharesHousehold;
154	    }
155	
156	    public void setSharesHousehold(Boolean sharesHousehold) {
157	        this.sharesHousehold = sharesHousehold;
158	    }
159	
160	    public String getLocality() {
161	        return this.locality;
162	    }
163	
164	    public void setLocality(String locality) {
165	        this.locality = locality;
166	    }
167	
168	    protected Set<Pet> getPetsInternal() {
169	        if (this.pets == null) {
170	            this.pets = new HashSet<>();
171	        }
172	        return this.pets;
173	    }
174	
175	    protected void setPetsInternal(Set<Pet> pets) {
176	        this.pets = pets;
177	    }
178	
179	    public List<Pet> getPets() {
180	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
181	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
182	        return Collections.unmodifiableList(sortedPets);
183	    }
184	
185	    public void setPets(List<Pet> pets) {
186	        this.pets = new HashSet<>(pets);
187	    }
188	
189	    public void addPet(Pet pet) {
190	        getPetsInternal().add(pet);
191	        pet.setOwner(this);
192	    }
193	
194	    /**
195	     * Return the Pet with the given name, or null if none found for this Owner.
196	     *
197	     * @param name to test
198	     * @return true if pet name is already in use
199	     */
200	    public Pet getPet(String name) {
201	        return getPet(name, false);
202	    }
203	
204	    /**
205	     * Return the Pet with the given name, or null if none found for this Owner.
206	     *
207	     * @param name to test
208	     * @return true if pet name is already in use
209	     */
210	    public Pet getPet(String name, boolean ignoreNew) {
211	        name = name.toLowerCase();
212	        for (Pet pet : getPetsInternal()) {
213	            if (!ignoreNew || !pet.isNew()) {
214	                String compName = pet.getName();
215	                compName = compName.toLowerCase();
216	                if (compName.equals(name)) {
217	                    return pet;
218	                }
219	            }
220	        }
221	        return null;
222	    }
223	
224	    public Pet getPet(Integer petId) {
225	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
226	    }
227	
228	    /**
229	     * Return the display name of this owner, formatted as 'LastName, FirstName'.
230	     *
231	     * @return the formatted display name
232	     */
233	    @Transient
234	    public String getDisplayName() {
235	        return this.getLastName() + ", " + this.getFirstName();
236	    }
237	
238	    /**
239	     * Return the initials of this owner, being the first letter of the first and
240	     * last name, upper-cased and dot-separated with a trailing dot, e.g. 'J.S.'.
241	     *
242	     * @return the formatted initials
243	     */
244	    @Transient
245	    public String getInitials() {
246	        return Character.toUpperCase(this.getFirstName().charAt(0)) + "."
247	            + Character.toUpperCase(this.getLastName().charAt(0)) + ".";
248	    }
249	
250	    @Override
251	    public String toString() {
252	        return new ToStringCreator(this)
253	
254	            .append("id", this.getId())
255	            .append("new", this.isNew())
256	            .append("lastName", this.getLastName())
257	            .append("firstName", this.getFirstName())
258	            .append("address", this.address)
259	            .append("city", this.city)
260	            .append("telephone", this.telephone)
261	            .toString();
262	    }
263	}
